import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs['target_snapshot'].copy()
    cdc = inputs['cdc_events'].copy()

    # --- Determine current watermark/reading per device from target_snapshot ---
    # If duplicate device_id rows exist in target_snapshot, keep the one with
    # the highest applied_event_ts as the "current" state (deterministic).
    if not target.empty:
        target_sorted = target.sort_values(['device_id', 'applied_event_ts'],
                                            kind='mergesort')
        current = target_sorted.groupby('device_id', as_index=False).last()
    else:
        current = target.copy()
        for col in ['device_id', 'reading', 'applied_event_ts']:
            if col not in current.columns:
                current[col] = pd.Series(dtype=object)

    watermarks = dict(zip(current['device_id'], current['applied_event_ts']))

    # --- Filter cdc events: only those strictly newer than the device's
    #     current watermark survive. Devices with no prior watermark accept
    #     all their events. ---
    if not cdc.empty:
        def survives(row):
            dev = row['device_id']
            if dev not in watermarks:
                return True
            wm = watermarks[dev]
            return row['event_ts'] > wm

        mask = cdc.apply(survives, axis=1)
        surviving = cdc[mask].copy()
    else:
        surviving = cdc.copy()

    # --- Among surviving events per device, the one with the greatest
    #     (event_ts, event_seq) wins. ---
    if not surviving.empty:
        surviving_sorted = surviving.sort_values(
            ['device_id', 'event_ts', 'event_seq'], kind='mergesort'
        )
        winners = surviving_sorted.groupby('device_id', as_index=False).last()
    else:
        winners = surviving.copy()
        for col in ['device_id', 'event_ts', 'event_seq', 'reading']:
            if col not in winners.columns:
                winners[col] = pd.Series(dtype=object)

    # --- Build the new snapshot: start from existing devices, apply winners,
    #     and add brand-new devices from winners that weren't in target. ---
    result_rows = {}

    for _, r in current.iterrows():
        result_rows[r['device_id']] = {
            'device_id': r['device_id'],
            'reading': r['reading'],
            'applied_event_ts': r['applied_event_ts'],
        }

    for _, r in winners.iterrows():
        result_rows[r['device_id']] = {
            'device_id': r['device_id'],
            'reading': r['reading'],
            'applied_event_ts': r['event_ts'],
        }

    out = pd.DataFrame(
        list(result_rows.values()),
        columns=['device_id', 'reading', 'applied_event_ts'],
    )

    return {'new_snapshot': out}
